func TestActualPillowBCnBitmapBranches(t *testing.T) {
	var rows []struct {
		Name      string
		Encoded   string `json:"encoded_base64"`
		Success   bool
		Mode      string `json:"loaded_mode"`
		Size      [2]int `json:"loaded_size"`
		PixelsSHA string `json:"raster_sha256"`
		Gray      []byte `json:"gray100"`
		Hash      string `json:"original_100bit_hash"`
		Error     *struct{ Class, Message string }
	}
	if err := json.Unmarshal([]byte(blockSourceCases), &rows); err != nil {
		t.Fatal(err)
	}
	for _, c := range rows {
		t.Run(c.Name, func(t *testing.T) {
			b, err := base64.StdEncoding.DecodeString(c.Encoded)
			if err != nil {
				t.Fatal(err)
			}
			checked := false
			r, recognized, err := legacycodec.Decode(b, func(w, h int) error { checked = true; return nil })
			if !recognized || !checked {
				t.Fatalf("recognized=%v dimensioncheck=%v", recognized, checked)
			}
			if !c.Success {
				if err == nil {
					t.Fatal("source rejected input but Go accepted")
				}
				if c.Error == nil || err.Error() != c.Error.Message {
					t.Fatalf("error got %v want source %v", err, c.Error)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if r.Mode != c.Mode || r.Width != c.Size[0] || r.Height != c.Size[1] {
				t.Fatalf("got %s %dx%d want source %s %v", r.Mode, r.Width, r.Height, c.Mode, c.Size)
			}
			if got := fmt.Sprintf("%x", sha256.Sum256(r.Pixels)); got != c.PixelsSHA {
				t.Errorf("decoded pixels SHA got %s want source %s", got, c.PixelsSHA)
			}
			rr := imagehash.Raster{Mode: r.Mode, Width: r.Width, Height: r.Height, Pixels: r.Pixels, Palette: r.Palette}
			gray, err := imagehash.Gray(rr, [2]int{10, 10})
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(gray, c.Gray) {
				t.Errorf("gray got %v want source %v", gray, c.Gray)
			}
			hash, err := imagehash.Raw(rr, [2]int{10, 10})
			if err != nil {
				t.Fatal(err)
			}
			if hash != c.Hash {
				t.Errorf("hash got %s want source %s", hash, c.Hash)
			}
		})
	}
}
